 function packageBody(id,x,y,w,h,d,color=black){const b=box(host.body,[w,h,d],[x,y,2.2-d/2],color,'Glass '+id+' actual fixed package');parts.push(b);return b;}
 const mcu=packageBody('U3 STM32F030F4P6 TSSOP20',-11,-7.8,4.4,6.4,.9),mcuPins=[];
 for(const sign of[-1,1])for(let i=0;i<10;i++){const y=-7.8+(i-4.5)*.65;mcuPins.push(box(host.body,[1.0,.25,.16],[-11+sign*2.45,y,2.08],metal,'Glass U3 actual TSSOP lead'));lands.push(box(host.body,[1.2,.38,.025],[-11+sign*2.48,y,2.1875],metal,'Glass U3 solder land'));}
 const buzzer=packageBody('fixed square buzzer carrier',11.7,-7.1,5,5,2.45);buzzer.userData={role:'fixed-buzzer-body',scope:'Actual package appearance only; no Speaker or audio synthesis'};for(const sign of[-1,1])terminals.push(box(host.body,[.6,1.0,.2],[11.7+sign*2.6,-7.1,2.1],metal,'Glass buzzer fixed terminal'));
 for(const[id,x,y,w,h,d]of[['U1 SGM6601',11,-16.5,2.8,1.6,.9],['U2 BL8075',-10.8,-16.8,2.8,1.6,.9],['L1 fixed inductor',8,-13.7,3,3,1.4],['Q1',-14.5,-13.4,2.1,1.3,.8]]){packageBody(id,x,y,w,h,d);for(const sign of[-1,1])terminals.push(box(host.body,[.55,h*.7,.15],[x+sign*(w/2+.14),y,2.1],metal,'Glass '+id+' fixed termination'));}
 const passivePositions=[[-15,-4.1],[-16.5,-5.2],[-15.2,-11.7],[-12,-12],[-8.9,-12],[-13,-14.2],[-13.6,-17.8],[-7.7,-16.4],[-8.7,-18],[14.8,-13.4],[15.2,-15.3],[14.2,-17.1],[6.1,-17.7],[5.9,-15.9],[11,-11],[12.5,-11],[8.5,-10.6],[7,-11.3],[-7,-4.3],[-8.6,-4.3],[-10.2,-4.3],[-11.8,-4.3],[-13.4,-4.3],[-15,-16.5],[-15.9,-18]];
 for(const[i,[x,y]]of passivePositions.entries()){const id=i<14?'C'+(i+1):'R'+(i-13);packageBody(id,x,y,.75,1.25,.45,i<14?ceramic:black);for(const sy of[-1,1]){terminals.push(box(host.body,[.78,.28,.46],[x,y+sy*.49,1.97],metal,'Glass '+id+' end cap'));lands.push(box(host.body,[.9,.45,.025],[x,y+sy*.52,2.1875],metal,'Glass '+id+' real solder land'));}}
 const diodes=[];for(const[x,y]of[[15.7,-11.6],[11.2,-18.1],[6.3,-12.3]]){diodes.push(packageBody('fixed diode',x,y,1.6,.8,.6));for(const sx of[-1,1])terminals.push(box(host.body,[.4,.8,.2],[x+sx*.7,y,2.1],metal,'Glass diode termination'));}
 const fpcBody=box(host.body,[13.6,2.3,1.05],[0,-8.4,1.675],materials.plastic(0xd9d7c4,{roughness:.7}),'Glass own24pin FPC connector dielectric'),latch=box(host.body,[13.6,.65,.45],[0,-7.35,1.05],black,'Glass fixed24pin FPC latch'),fpcContacts=[];
